import {sampleComposite,disciplines,clone,utMatrix,metrics} from './composite-engine.mjs';
import {createSession,changeModel,checkSession,proposeSession,applyCandidate,reviewSession,reportSession} from './composite-state.mjs';
import {evidence} from './research.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=createSession(sampleComposite()),selected='PIPE-02';checkSession(state);
let reportUrl=null;
const number=n=>n.toFixed(1),labels={clash:'체적 간섭',band:'높이 구간',clearance:'최소 이격',boundary:'영역 경계','ut-missing':'UT 미연결','ut-kind':'UT 공종','ut-capacity':'UT 용량'};
const notice=message=>{$('c-message').textContent=message;};
function action(fn){try{const result=fn();render();return result;}catch(error){notice(error.message);return {error:error.message};}}
function draw(){
 const m=state.model,issues=state.checkedRevision===state.revision?state.issues:[],affected=new Set(issues.flatMap(i=>[i.a,i.b]));
 $('c-plan').innerHTML=`<defs><pattern id="c-grid" width="2" height="2" patternUnits="userSpaceOnUse"><path d="M2 0H0V2" stroke="#33505e" stroke-width=".04" fill="none"/></pattern></defs><rect width="60" height="36" fill="url(#c-grid)" stroke="#668392" stroke-width=".1"/>`+m.obstacles.map(o=>`<rect x="${o.x}" y="${o.y}" width="${o.sizeX}" height="${o.sizeY}" fill="#52626c" fill-opacity=".45" stroke="#839da9" stroke-width=".08" stroke-dasharray=".4 .3"/>`).join('')+m.objects.map(o=>`<g><rect x="${o.x}" y="${o.y}" width="${o.sizeX}" height="${o.sizeY}" fill="${disciplines[o.kind].color}" fill-opacity=".35" stroke="${affected.has(o.id)?'#ff8b7c':disciplines[o.kind].color}" stroke-width="${selected===o.id?.28:.13}"/><text x="${o.x+.2}" y="${o.y-.4}" fill="${disciplines[o.kind].color}" font-size=".85">${esc(o.id)}</text></g>`).join('')+m.supplies.map(s=>`<g><circle cx="${s.x}" cy="${s.y}" r=".4" fill="${disciplines[s.kind].color}"/><text x="${Math.min(52,s.x+1)}" y="${Math.max(1,s.y-1)}" fill="#e6f2f5" font-size=".8">${esc(s.id)}</text></g>`).join('');
 $('c-elevation').innerHTML=m.objects.map(o=>`<div class="elevation-row"><span>${esc(o.id)}</span><div class="height-track"><i style="left:${o.z/8*100}%;width:${o.sizeZ/8*100}%;background:${disciplines[o.kind].color}"></i></div><span>${number(o.z)}–${number(o.z+o.sizeZ)} m</span></div>`).join('');
}
function render(){
 const m=state.model,current=state.checkedRevision===state.revision;
 if(reportUrl){URL.revokeObjectURL(reportUrl);reportUrl=null;}$('c-report-preview').hidden=true;$('c-report-json').textContent='';$('c-report-download').removeAttribute('href');
 $('c-revision').textContent=`검토 개정 R${state.revision}`;$('c-count').textContent=current?`${state.issues.length}건`:'재검사 필요';$('c-review-state').textContent=state.reviewedRevision===state.revision?'샘플 검토 완료':current&&!state.issues.length?'설계자 검토 대기':'조건 검토 중';$('c-distance').textContent=`${number(metrics(m).connection)} m`;
 $('c-review').disabled=!current||state.issues.length>0||state.reviewedRevision===state.revision;
 $('c-objects').innerHTML=m.objects.map(o=>`<button type="button" data-object="${esc(o.id)}" class="c-object ${selected===o.id?'selected':''}" aria-pressed="${selected===o.id}"><i style="background:${disciplines[o.kind].color}"></i><span><b>${esc(o.id)}</b><small>${esc(o.layer)} · Z ${number(o.z)} m</small></span><em>${o.hold?'Hold':o.locked?'고정':''}</em></button>`).join('');
 for(const button of $('c-objects').querySelectorAll('button'))button.onclick=()=>{selected=button.dataset.object;render();};
 $('c-issues').innerHTML=!current?'<p class="c-empty">조건이 변경되었습니다. 현재 개정을 재검사하세요.</p>':state.issues.length?state.issues.map(i=>`<div class="c-issue"><span>${labels[i.type]||esc(i.type)}</span><b>${esc(i.a)} ↔ ${esc(i.b)}</b><p>${esc(i.message)}</p></div>`).join(''):'<p class="c-empty">예시 필수 조건 0건<br>설계자 검토와 실제 DWG 확인은 별도로 진행하세요.</p>';
 const o=m.objects.find(o=>o.id===selected)||m.objects[0];selected=o.id;$('c-selected').textContent=o.id;const form=$('c-properties');
 for(const key of ['x','y','z','sizeX','sizeY','sizeZ','demand','layer','sourceRevision'])form.elements[key].value=o[key];for(const key of ['locked','hold'])form.elements[key].checked=o[key];
 form.elements.pocId.innerHTML='<option value="">미연결</option>'+m.supplies.map(s=>`<option value="${esc(s.id)}">${esc(s.id)} · ${esc(s.unit)}</option>`).join('');form.elements.pocId.value=o.pocId;
 $('c-ut-body').innerHTML=utMatrix(m).map(s=>`<tr><th scope="row">${esc(s.id)}<small>${disciplines[s.kind].label} · ${esc(s.unit)}</small></th><td>${s.used}</td><td><input aria-label="${esc(s.id)} 공급 용량" data-supply="${esc(s.id)}" type="number" min="0" step="any" value="${s.capacity}" required></td><td class="${s.remaining<0?'danger':''}">${number(s.remaining)}</td><td>${esc(s.objects.join(', ')||'없음')}</td></tr>`).join('');
 $('c-clearance').value=m.clearance;for(const [kind,band] of Object.entries(m.bands)){ $( `c-${kind}-lo`).value=band[0];$(`c-${kind}-hi`).value=band[1];}
 $('c-candidates').innerHTML=state.candidates.length?state.candidates.map((c,i)=>`<article class="candidate"><div class="eyebrow">대안 ${i+1} · R${c.revision}</div><h3>${c.strategy==='movement'?'이동 최소':'연결거리 우선'}</h3>${c.ok?`<dl><div><dt>필수 위반</dt><dd>${c.metrics.issues}건</dd></div><div><dt>이동 객체 / 이동량</dt><dd>${c.metrics.moved}개 / ${number(c.metrics.movement)} m</dd></div><div><dt>POC 거리 추정 합</dt><dd>${number(c.metrics.connection)} m</dd></div></dl><button class="button quiet" data-candidate="${i}">대안 ${i+1} 적용</button>`:`<p>${esc(c.reason)}</p><button class="button quiet" disabled>적용 불가</button>`}</article>`).join(''):'<p class="c-empty">현재 개정에서 두 배치 대안을 생성해 이동량과 공급점 거리를 비교하세요.</p>';
 for(const button of $('c-candidates').querySelectorAll('[data-candidate]'))button.onclick=()=>action(()=>{applyCandidate(state,state.candidates[Number(button.dataset.candidate)]);notice('대안 적용 후 재검사를 통과했습니다. 샘플 검토를 진행하세요.');});
 $('c-history').innerHTML=state.events.length?state.events.slice(0,15).map(e=>`<li><b>R${e.revision}</b><span>${esc(e.reason)}</span><time>${esc(new Date(e.time).toLocaleTimeString('ko-KR'))}</time></li>`).join(''):'<li>이 탭에서 수행한 변경과 검토 이력이 표시됩니다.</li>';
 $('process-composite-result').textContent=`컴포짓 R${state.revision} · ${current?`필수 위반 ${state.issues.length}건`:'재검사 필요'} · ${$('c-review-state').textContent}`;
 draw();
}
export function initComposite(){
 $('c-check').onclick=()=>action(()=>{checkSession(state);notice(`R${state.revision} 검사 완료: 필수 위반 ${state.issues.length}건`);});
 $('c-propose').onclick=()=>action(()=>{const results=proposeSession(state);notice(results.some(c=>c.ok)?'현재 개정에서 대안을 생성했습니다. 적용 전에 지표를 비교하세요.':'대안 생성 불가: 조건과 UT 상태를 확인하세요.');});
 $('c-review').onclick=()=>action(()=>{reviewSession(state);notice('현재 개정의 샘플 검토 완료를 기록했습니다. 실제 설계 승인을 대신하지 않습니다.');});
 $('c-reset').onclick=()=>action(()=>{changeModel(state,sampleComposite(),'예시 조건으로 초기화');checkSession(state);notice('예시 모델로 초기화했습니다.');});
 $('c-properties').onsubmit=e=>{e.preventDefault();action(()=>{const form=e.currentTarget,m=clone(state.model),o=m.objects.find(o=>o.id===selected),next={...o};for(const k of ['x','y','z','sizeX','sizeY','sizeZ','demand'])next[k]=Number(form.elements[k].value);for(const k of ['locked','hold'])next[k]=form.elements[k].checked;for(const k of ['layer','sourceRevision','pocId'])next[k]=form.elements[k].value.trim();if((o.locked||o.hold)&&(next.locked||next.hold)&&['x','y','z','sizeX','sizeY','sizeZ'].some(k=>o[k]!==next[k]))throw new Error('고정·Hold를 해제한 뒤 형상을 변경하세요.');Object.assign(o,next);changeModel(state,m,form.elements.reason.value);form.elements.reason.value='';notice('객체·UT 변경을 기록했습니다. 이전 대안과 검토 완료 상태가 해제되었습니다.');});};
 $('c-conditions').onsubmit=e=>{e.preventDefault();action(()=>{const m=clone(state.model);m.clearance=Number($('c-clearance').value);for(const kind of Object.keys(disciplines))m.bands[kind]=[Number($(`c-${kind}-lo`).value),Number($(`c-${kind}-hi`).value)];for(const input of $('c-ut-body').querySelectorAll('input'))m.supplies.find(s=>s.id===input.dataset.supply).capacity=Number(input.value);changeModel(state,m,e.currentTarget.elements.conditionReason.value);e.currentTarget.elements.conditionReason.value='';notice('높이·이격·UT 공급 조건을 변경했습니다. 재검사가 필요합니다.');});};
 $('c-report').onclick=()=>{const json=JSON.stringify(reportSession(state),null,2);if(reportUrl)URL.revokeObjectURL(reportUrl);reportUrl=URL.createObjectURL(new Blob([json],{type:'application/json;charset=utf-8'}));$('c-report-json').textContent=json;const a=$('c-report-download');a.href=reportUrl;a.download=`composite-review-R${state.revision}.json`;$('c-report-preview').hidden=false;notice('현재 개정의 검토 기록을 아래에 생성했습니다. JSON 파일 저장 링크로 내려받을 수 있습니다.');};
 $('c-evidence').innerHTML=evidence.map(e=>`<article><div class="eyebrow">${esc(e.status)}</div><h3>${esc(e.company)}</h3><b>${esc(e.title)}</b><p>${esc(e.finding)}</p><p class="applied"><strong>반영</strong> ${esc(e.applied)}</p><p class="subtle">${esc(e.limit)}</p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.source)} ↗</a>${e.extraUrl?` · <a href="${esc(e.extraUrl)}" target="_blank" rel="noopener noreferrer">${esc(e.extraSource)} ↗</a>`:''}</article>`).join('');
 render();
 if(document.modelContext?.registerTool){const abort=new AbortController(),empty={type:'object',properties:{},additionalProperties:false},validate=input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('빈 객체가 필요합니다.');};for(const tool of [{name:'inspect_composite',description:'현재 개정의 예시 2.5D 컴포짓 형상, UT, 검토 상태를 읽습니다. 검사 상태를 변경하지 않습니다.',annotations:{readOnlyHint:true},execute(input){validate(input);return reportSession(state);}},{name:'propose_composite',description:'현재 개정을 검사하고 두 배치 대안을 생성합니다. 적용하지 않습니다.',annotations:{readOnlyHint:false},execute(input){validate(input);const result=proposeSession(state);render();return result.map(c=>({ok:c.ok,strategy:c.strategy,revision:c.revision,metrics:c.metrics,reason:c.reason}));}}]){try{Promise.resolve(document.modelContext.registerTool({...tool,inputSchema:empty},{signal:abort.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>abort.abort(),{once:true});}
}
